def determine_music_genre(career_stage, past_genres):
	if career_stage == 'early':
		return 'rock'
	elif career_stage == 'mid':
		if past_genres == ['rock', 'pop']:
			return 'pop'
		else:
			return 'blues'
	elif career_stage == 'late':
		if past_genres == ['rock', 'blues'] or past_genres == ['pop', 'blues']:
			return 'blues'
		else:
			return 'gospel'

